const KEYWORDS = [
  "async remote","asynchronous remote","worldwide remote","global remote",
  "work from anywhere","remote data analyst","remote data scientist",
  "remote ai marketing","remote marketing analyst","remote growth analyst",
  "remote bi analyst","remote automation specialist","remote ai workflow consultant"
];

const HARD_REJECT_PATTERNS = [
  "us only","u\\.s\\. only","usa only","canada only","uk only","u\\.k\\. only",
  "eu only","e\\.u\\. only","europe only","australia only",
  "must be based in","must live in","must be authorized to work in",
  "local work permit required","\\bhybrid\\b","\\bonsite\\b","on-site",
  "office required","remote within .*only","remote \\(.*only\\)",
  "fixed us hours","fixed eu hours","fixed est hours","fixed pst hours","fixed cet hours"
];

const HARD_KEEP_PATTERNS = [
  "worldwide remote","global remote","work from anywhere","\\banywhere\\b",
  "apac remote","international contractors","contractor role","b2b contractor",
  "hires via deel","hires via remote\\.com","hires via oyster","eor supported",
  "remote first","remote-first","distributed team"
];

const ASYNC_KEEP_PATTERNS = [
  "\\basync\\b","asynchronous","flexible hours","flexible schedule",
  "distributed team","remote first","remote-first","low meeting culture",
  "work across time zones","work across timezones"
];

const ASYNC_REJECT_PATTERNS = [
  "strict 9 to 5","strict 9-to-5","fixed us hours","fixed est hours","fixed pst hours",
  "fixed cet hours","daily live calls required","must overlap full business day"
];

const ROLE_KEYWORDS = [
  { pattern: "data analyst", category: "Data Analyst", weight: 25 },
  { pattern: "data scientist", category: "Data Scientist", weight: 25 },
  { pattern: "junior data scientist", category: "Data Scientist", weight: 25 },
  { pattern: "business intelligence analyst", category: "BI Analyst", weight: 25 },
  { pattern: "\\bbi analyst\\b", category: "BI Analyst", weight: 25 },
  { pattern: "marketing analyst", category: "Marketing Analyst", weight: 25 },
  { pattern: "performance marketing analyst", category: "Marketing Analyst", weight: 25 },
  { pattern: "growth analyst", category: "Growth Analyst", weight: 25 },
  { pattern: "ai marketing specialist", category: "AI Marketing", weight: 25 },
  { pattern: "ai automation specialist", category: "AI Automation", weight: 25 },
  { pattern: "ai workflow consultant", category: "AI Workflow Consultant", weight: 25 },
  { pattern: "creative strategist", category: "Creative Strategist", weight: 15 },
  { pattern: "martech analyst", category: "MarTech Analyst", weight: 15 }
];

return [{
  json: {
    keywords: KEYWORDS,
    hardRejectPatterns: HARD_REJECT_PATTERNS,
    hardKeepPatterns: HARD_KEEP_PATTERNS,
    asyncKeepPatterns: ASYNC_KEEP_PATTERNS,
    asyncRejectPatterns: ASYNC_REJECT_PATTERNS,
    roleKeywords: ROLE_KEYWORDS,
    spreadsheetId: "PUT_YOUR_GOOGLE_SHEET_ID_HERE",
    telegramChatId: "PUT_YOUR_TELEGRAM_CHAT_ID_HERE",
    digestEmailTo: "you@example.com"
  }
}];

function hashId(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

function stripHtml(html) {
  return String(html || "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
}

const out = [];

for (const item of items) {
  const j = item.json;
  let normalized = null;

  if (j.job_url) {
    // Already-normalized shape - used by custom/scraper sources wired in later.
    normalized = {
      job_title: j.job_title || "",
      company: j.company || "",
      job_url: j.job_url,
      source: j.source || j._source || "Unknown",
      location_text: j.location_text || "",
      salary: j.salary || "",
      description: j.description || "",
      posted_date: j.posted_date || "",
      tags: j.tags || ""
    };
  } else if (j.slug !== undefined && j.position !== undefined) {
    // Remote OK
    normalized = {
      job_title: j.position || j.title || "",
      company: j.company || "",
      job_url: j.url || j.apply_url || "",
      source: "Remote OK",
      location_text: j.location || "",
      salary: (j.salary_min && j.salary_max) ? `${j.salary_min}-${j.salary_max}` : (j.salary || ""),
      description: stripHtml(j.description),
      posted_date: j.date || "",
      tags: Array.isArray(j.tags) ? j.tags.join(", ") : (j.tags || "")
    };
  } else if (j.candidate_required_location !== undefined) {
    // Remotive
    normalized = {
      job_title: j.title || "",
      company: j.company_name || "",
      job_url: j.url || "",
      source: "Remotive",
      location_text: j.candidate_required_location || "",
      salary: j.salary || "",
      description: stripHtml(j.description),
      posted_date: j.publication_date || "",
      tags: Array.isArray(j.tags) ? j.tags.join(", ") : (j.tags || "")
    };
  } else if (j.title !== undefined && j.link !== undefined) {
    // We Work Remotely RSS item - title is usually "Company: Job Title"
    const rawTitle = (j.title || "").toString();
    let company = "";
    let jobTitle = rawTitle;
    const splitIdx = rawTitle.indexOf(": ");
    if (splitIdx > -1) {
      company = rawTitle.slice(0, splitIdx).trim();
      jobTitle = rawTitle.slice(splitIdx + 2).trim();
    }
    const desc = j.description ? (j.description["#text"] || j.description) : "";
    normalized = {
      job_title: jobTitle,
      company: company,
      job_url: (j.link || "").toString(),
      source: "We Work Remotely",
      location_text: "",
      salary: "",
      description: stripHtml(desc),
      posted_date: (j.pubDate || "").toString(),
      tags: j.category ? [].concat(j.category).join(", ") : ""
    };
  }

  if (!normalized || !normalized.job_url) continue;

  normalized.job_id = hashId(normalized.job_url);
  out.push({ json: normalized });
}

return out;

const cfg = $('Config').first().json;
const kw = cfg.keywords.map(k => k.toLowerCase());

return items.filter(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  return kw.some(k => haystack.includes(k));
});

const existing = $('Get Existing Raw Jobs').all().map(i => i.json);
const existingUrls = new Set(existing.map(r => (r.job_url || "").trim()));
const existingCompanyTitle = new Set(
  existing.map(r => `${(r.company || "").trim().toLowerCase()}|${(r.job_title || "").trim().toLowerCase()}`)
);

const seenThisRun = new Set();
const out = [];

for (const item of items) {
  const j = item.json;
  const urlKey = (j.job_url || "").trim();
  const ctKey = `${(j.company || "").trim().toLowerCase()}|${(j.job_title || "").trim().toLowerCase()}`;

  if (!urlKey) continue;
  if (existingUrls.has(urlKey)) continue;
  if (existingCompanyTitle.has(ctKey)) continue;
  if (seenThisRun.has(urlKey) || seenThisRun.has(ctKey)) continue;

  seenThisRun.add(urlKey);
  seenThisRun.add(ctKey);
  out.push({ json: { ...j, date_found: new Date().toISOString().slice(0, 10) } });
}

return out;

const cfg = $('Config').first().json;
const rejectRe = new RegExp(cfg.hardRejectPatterns.join("|"), "i");
const keepRe = new RegExp(cfg.hardKeepPatterns.join("|"), "i");

return items.map(item => {
  const j = item.json;
  const haystack = `${j.description} ${j.location_text} ${j.job_title}`;

  const hasReject = rejectRe.test(haystack);
  const hasKeep = keepRe.test(haystack);

  let hard_filter = "unclear";
  let hard_reject_reason = "";

  if (hasReject) {
    hard_filter = "reject";
    const match = haystack.match(rejectRe);
    hard_reject_reason = match ? match[0] : "restricted location / onsite language";
  } else if (hasKeep) {
    hard_filter = "keep";
  }

  return { json: { ...j, hard_filter, hard_reject_reason } };
});

return items.map(item => {
  const j = item.json;
  return { json: {
    date_rejected: new Date().toISOString().slice(0, 10),
    job_title: j.job_title,
    company: j.company,
    job_url: j.job_url,
    reason: `Hard filter: ${j.hard_reject_reason}`
  }};
});

const original = $('Loop Over Items').item.json;
const aiRaw = $json;

let aiResult = {
  taiwan_eligible: "unclear",
  reason: "Could not parse AI response",
  location_risk: "medium",
  timezone_risk: "medium",
  contractor_possible: "unclear",
  decision: "manual_check"
};

try {
  const text = (aiRaw.content && aiRaw.content[0] && aiRaw.content[0].text) || "";
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    aiResult = { ...aiResult, ...parsed };
  }
} catch (e) {
  // keep fallback aiResult - flagged as manual_check downstream
}

return [{
  json: {
    ...original,
    ai_taiwan_eligible: aiResult.taiwan_eligible,
    ai_reason: aiResult.reason,
    ai_location_risk: aiResult.location_risk,
    ai_timezone_risk: aiResult.timezone_risk,
    ai_contractor_possible: aiResult.contractor_possible,
    ai_decision: aiResult.decision
  }
}];

const cfg = $('Config').first().json;
const keepRe = new RegExp(cfg.asyncKeepPatterns.join("|"), "i");
const rejectRe = new RegExp(cfg.asyncRejectPatterns.join("|"), "i");

return items.map(item => {
  const j = item.json;
  const haystack = `${j.description} ${j.tags}`;
  const rejected = rejectRe.test(haystack);
  let async_level = "unclear";
  if (rejected) async_level = "reject";
  else if (keepRe.test(haystack)) async_level = "high";
  return { json: { ...j, async_level } };
});

const cfg = $('Config').first().json;

return items.map(item => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  let role_category = "";
  let role_points = 0;
  for (const r of cfg.roleKeywords) {
    if (new RegExp(r.pattern, "i").test(haystack)) {
      role_category = r.category;
      role_points = r.weight;
      break;
    }
  }
  if (!role_category) {
    role_category = "Adjacent / General Remote";
    role_points = 15;
  }
  return { json: { ...j, role_category, role_points } };
});

return items.map(item => {
  const j = item.json;
  let score = 0;

  // Taiwan eligibility (max 40)
  const elig = (j.ai_taiwan_eligible || "").toLowerCase();
  const locRisk = (j.ai_location_risk || "").toLowerCase();
  if (elig === "yes" && locRisk === "low") score += 40;
  else if (elig === "yes") score += 30;
  else if (elig === "unclear" && locRisk !== "high") score += 20;

  // Async fit (max 25)
  const haystack = `${j.description}`.toLowerCase();
  if (j.async_level === "high") score += 25;
  else if (j.async_level === "unclear") score += 10;
  if (/distributed team/.test(haystack) && j.async_level !== "high") score += 15;
  else if (/remote[- ]first/.test(haystack) && j.async_level !== "high" && !/distributed team/.test(haystack)) score += 10;

  // Role fit (max 25)
  score += j.role_points || 0;

  // Salary fit (max 25)
  const salaryText = (j.salary || "").toString();
  const hasSalary = salaryText.trim().length > 0;
  const salaryNumbers = salaryText.match(/\d[\d,]*/g) || [];
  const maxSalary = salaryNumbers.length ? Math.max(...salaryNumbers.map(n => parseInt(n.replace(/,/g, ""), 10))) : 0;
  let salaryScore = 0;
  if (hasSalary) salaryScore = 10;
  if (maxSalary >= 3000) salaryScore = 15;
  if (maxSalary >= 5000) salaryScore = 25;
  score += salaryScore;

  score = Math.max(0, Math.min(100, Math.round(score)));

  return { json: { ...j, score } };
});

return items.map(item => {
  const j = item.json;
  const elig = (j.ai_taiwan_eligible || "").toLowerCase();
  const locRisk = (j.ai_location_risk || "").toLowerCase();
  const tzRisk = (j.ai_timezone_risk || "").toLowerCase();

  let _bucket = "reject";
  let decision = "reject";
  let reject_reason = "";

  if (elig === "no") {
    reject_reason = "Taiwan eligibility: no";
  } else if (locRisk === "high") {
    reject_reason = "Location risk: high";
  } else if (tzRisk === "high") {
    reject_reason = "Timezone risk: high";
  } else if (j.async_level === "reject") {
    reject_reason = "Fixed/rigid working hours";
  } else if (j.score < 70) {
    reject_reason = `Score below 70 (${j.score})`;
  } else {
    _bucket = "filtered";
    const asyncOk = j.async_level === "high" || j.async_level === "unclear";
    const tzOk = tzRisk === "low" || tzRisk === "medium";
    if (elig === "yes" && j.score >= 85 && asyncOk && locRisk === "low" && tzOk) {
      decision = "apply_immediately";
    } else if (elig === "unclear" && j.score >= 85 && locRisk === "medium") {
      decision = "manual_check";
    } else {
      decision = "keep";
    }
  }

  const instant_alert = _bucket === "filtered" && j.score >= 85;

  return { json: {
    ...j,
    _bucket,
    decision,
    reject_reason,
    instant_alert,
    cover_letter_candidate: instant_alert
  }};
});

return items.map(item => {
  const j = item.json;
  return { json: {
    date_rejected: new Date().toISOString().slice(0, 10),
    job_title: j.job_title,
    company: j.company,
    job_url: j.job_url,
    reason: j.reject_reason
  }};
});

return items.map(item => {
  const j = item.json;
  return { json: {
    date_found: j.date_found || new Date().toISOString().slice(0, 10),
    score: j.score,
    job_title: j.job_title,
    company: j.company,
    job_url: j.job_url,
    salary: j.salary,
    taiwan_eligible: j.ai_taiwan_eligible,
    taiwan_reason: j.ai_reason,
    location_risk: j.ai_location_risk,
    timezone_risk: j.ai_timezone_risk,
    contractor_possible: j.ai_contractor_possible,
    async_level: j.async_level,
    role_category: j.role_category,
    why_good_fit: j.ai_reason,
    decision: j.decision,
    application_status: j.decision === "apply_immediately" ? "ready to apply"
      : (j.decision === "manual_check" ? "needs manual review" : "new"),
    notes: ""
  }};
});

