const original = $('Filter Cover Letter Candidates').item.json;
const aiRaw = $json;
let coverLetter = "";
try {
  coverLetter = (aiRaw.content && aiRaw.content[0] && aiRaw.content[0].text) || "";
} catch (e) {
  coverLetter = "";
}
return [{ json: {
  date_found: original.date_found || new Date().toISOString().slice(0, 10),
  job_title: original.job_title,
  company: original.company,
  job_url: original.job_url,
  score: original.score,
  cover_letter_draft: coverLetter
} }];

const all = items.map(i => i.json);
const filtered = all.filter(j => j._bucket === "filtered").sort((a, b) => b.score - a.score);
const rejected = all.filter(j => j._bucket === "reject");
const top = filtered.slice(0, 10);
const manualCheck = filtered.filter(j => j.decision === "manual_check");

// Hard-filter rejects (US/EU/hybrid language) exit the pipeline before
// reaching this node, so pull their reasons directly from that earlier
// node's full output instead of only the post-AI reject bucket.
const hardRejected = $('Hard Filter Taiwan Keywords').all()
  .map(i => i.json)
  .filter(j => j.hard_filter === "reject");

const reasonPool = [
  ...rejected.map(j => j.reject_reason || ""),
  ...hardRejected.map(j => `Hard filter: ${j.hard_reject_reason || ""}`)
];

const rejectedCounts = {
  usOnly: reasonPool.filter(r => /us only/i.test(r)).length,
  euOnly: reasonPool.filter(r => /eu only|europe only/i.test(r)).length,
  hybrid: reasonPool.filter(r => /hybrid|onsite/i.test(r)).length,
  timezoneRisk: reasonPool.filter(r => /timezone risk/i.test(r)).length
};

function jobBlock(j, idx) {
  return [
    `${idx + 1}. ${j.job_title}`,
    `Company: ${j.company}`,
    `Score: ${j.score}`,
    `Taiwan eligible: ${j.ai_taiwan_eligible}`,
    `Reason: ${j.ai_reason}`,
    `Async level: ${j.async_level}`,
    `Timezone risk: ${j.ai_timezone_risk}`,
    `Salary: ${j.salary || "not listed"}`,
    `Why it fits Jerry: ${j.ai_reason}`,
    `Apply link: ${j.job_url}`
  ].join("\n");
}

let text = "Daily Taiwan Eligible Async Remote Jobs\n\n";
text += "Top jobs today:\n\n";
text += top.length ? top.map(jobBlock).join("\n\n") : "No jobs cleared the bar today.";
text += "\n\nManual check:\n";
text += manualCheck.length
  ? manualCheck.map(j => `- ${j.job_title} at ${j.company} (score ${j.score}) - ${j.job_url}`).join("\n")
  : "None.";
text += "\n\nRejected summary:\n";
text += `US only: ${rejectedCounts.usOnly}\n`;
text += `EU only: ${rejectedCounts.euOnly}\n`;
text += `Hybrid/onsite: ${rejectedCounts.hybrid}\n`;
text += `Timezone risk: ${rejectedCounts.timezoneRisk}\n`;

return [{ json: { digestText: text, topCount: top.length, rejectedCount: rejected.length } }];
